Answer.ValidationCode:
$ErrorActionPreference = 'Stop'
try {
    $program = 'gpasswd'
    $path = [regex]::Escape('/usr/bin/' + $program)
    $key = [regex]::Escape('privileged-' + $program)
    $status = @(& auditctl -s 2>&1)
    if ($LASTEXITCODE -ne 0 -or ($status -join "`n") -notmatch '(?m)^enabled\s+[12]$' -or
        ($status -join "`n") -notmatch '(?m)^pid\s+[1-9][0-9]*$') {
        throw 'Cannot confirm that kernel auditing and auditd are enabled.'
    }
    $runtime = @(& auditctl -l 2>&1)
    if ($LASTEXITCODE -ne 0) { throw 'auditctl -l failed.' }
    $persistent = @(Get-Content -LiteralPath '/etc/audit/rules.d/30-rhel10-stig.rules')
    $compiled = @(Get-Content -LiteralPath '/etc/audit/audit.rules')
    # Refuse an override when a potentially suppressing task/exit rule is present.
    if (($runtime -join "`n") -match '(?m)^-a\s+(?:never,(?:task|exit)|(?:task|exit),never)(?:\s|$)') {
        throw 'Potentially suppressing audit rule requires manual review.'
    }
    $evidence = @()
    foreach ($arch in @('b32', 'b64')) {
        # Anchoring rejects extra auid, success, uid, or other restrictive filters.
        # auditctl expands perm=x to execve,execveat on this RHEL release.
        $pattern = '^\s*-a always,exit -F arch=' + $arch +
            '(?: -S (?:all|execve,execveat|execveat,execve))? -F path=' + $path +
            ' -F perm=x (?:-k |-F key=)' + $key + '\s*$'
        foreach ($source in @('runtime', 'persistent', 'compiled')) {
            $lines = switch ($source) {
                'runtime' { $runtime }
                'persistent' { $persistent }
                'compiled' { $compiled }
            }
            $matches = @($lines | Where-Object { $_ -cmatch $pattern })
            if ($matches.Count -eq 0) { throw "Missing unfiltered $arch rule in $source for $program." }
            $evidence += "${source}: $($matches[0])"
        }
    }
    return @{ Valid = $true; Results = "Live DISA V1R3 validation for $program passed.`n" + ($evidence -join "`n") }
}
catch {
    return @{ Valid = $false; Results = "Custom validation failed; finding remains Open: $($_.Exception.Message)" }
}

