$ErrorActionPreference = 'Stop'
try {
    $file = 'password-auth'
    $integrity = @(& authselect check 2>&1)
    if ($LASTEXITCODE -ne 0) { throw 'authselect integrity check failed.' }
    $current = @(& authselect current --raw 2>&1)
    if ($LASTEXITCODE -ne 0) { throw 'Cannot read authselect profile.' }
    $profile = (($current -join ' ').Trim() -split '\s+')[0]
    if ($profile -cnotmatch '^custom/[A-Za-z0-9_-]+$') { throw 'Expected a custom authselect profile.' }
    if (-not (Test-Path -LiteralPath '/usr/lib64/security/pam_pwquality.so' -PathType Leaf)) {
        throw 'pwquality PAM module missing.'
    }
    $evidence = @()
    $quality = @()
    foreach ($path in @("/etc/pam.d/$file", "/etc/authselect/$profile/$file")) {
        $lines = @(Get-Content -LiteralPath $path)
        $password = @($lines | Where-Object { $_ -cmatch '^\s*password\s+' })
        $matches = @($password | Where-Object { $_ -cmatch '\bpam_pwquality[.]so(?:\s|$)' })
        if ($matches.Count -ne 1 -or $password.Count -eq 0 -or $matches[0] -cne $password[0]) {
            throw "Missing, duplicate, or bypassable pwquality rule in $path."
        }
        # Only the known unconditional enforcing layout is eligible for this exception.
        # local_users_only is the existing authselect profile option, not a waiver.
        if ($matches[0] -cnotmatch '^\s*password\s+(required|requisite)\s+pam_pwquality[.]so(?:\s+local_users_only)?\s*$') {
            throw "Unsupported control, arguments, or conditional rule in $path."
        }
        $quality += ($matches[0].Trim() -replace '\s+', ' ')
        $evidence += "${path}: $($matches[0])"
    }
    if ($quality[0] -cne $quality[1]) { throw 'Active and persistent quality rules differ.' }
    return @{ Valid = $true; Results = "Live $file pwquality enforcement verified; authselect integrity valid.`n" + ($evidence -join "`n") }
}
catch {
    return @{ Valid = $false; Results = "Validation failed; finding remains Open: $($_.Exception.Message)" }
}

