$ErrorActionPreference = 'Stop'
try {
    function Run-Checked([string]$Program, [string[]]$Arguments) {
        $value = @(& $Program @Arguments 2>&1)
        if ($LASTEXITCODE -ne 0) { throw "$Program failed: $value" }
        return ($value -join "`n").Trim()
    }
    Run-Checked 'rpm' @('-q', 'aide', 's-nail', 'postfix') | Out-Null
    foreach ($unit in @('postfix.service', 'rhel10-stig-aide.timer')) {
        if ((Run-Checked 'systemctl' @('is-enabled', $unit)) -cne 'enabled') { throw "$unit is not enabled" }
        if ((Run-Checked 'systemctl' @('is-active', $unit)) -cne 'active') { throw "$unit is not active" }
    }
    $next = Run-Checked 'systemctl' @('show', 'rhel10-stig-aide.timer', '--property=NextElapseUSecRealtime', '--value')
    if ([string]::IsNullOrWhiteSpace($next) -or $next -eq 'n/a') { throw 'No next scheduled scan' }
    if ((Run-Checked 'systemctl' @('show', 'rhel10-stig-aide.timer', '--property=NeedDaemonReload', '--value')) -ne 'no') { throw 'Pending unit reload' }
    if ((Run-Checked 'systemctl' @('show', 'rhel10-stig-aide.service', '--property=NeedDaemonReload', '--value')) -ne 'no') { throw 'Pending service reload' }
    if ((Run-Checked 'systemctl' @('show', 'rhel10-stig-aide.service', '--property=ExecStart', '--value')) -notmatch 'path=/usr/local/sbin/rhel10-stig-aide-check ; argv\[\]=/usr/local/sbin/rhel10-stig-aide-check ;') { throw 'Unexpected effective scan command' }
    foreach ($unit in @('rhel10-stig-aide.timer', 'rhel10-stig-aide.service')) {
        $dropins = Run-Checked 'systemctl' @('show', $unit, '--property=DropInPaths', '--value')
        if ($dropins) { throw 'Unit overrides require review' }
        if ((Run-Checked 'systemctl' @('show', $unit, '--property=FragmentPath', '--value')) -cne "/etc/systemd/system/$unit") { throw 'Unexpected unit source' }
    }
    if ((Get-Item '/var/lib/aide/aide.db.gz').Length -le 0) { throw 'Missing AIDE baseline' }
    if ((Run-Checked 'postconf' @('-h', 'alias_maps')) -cne 'lmdb:/etc/aliases') { throw 'Unsupported mail alias map' }
    $recipient = Run-Checked 'postmap' @('-q', 'root', 'lmdb:/etc/aliases')
    if ([string]::IsNullOrWhiteSpace($recipient) -or $recipient -eq 'root') { throw 'Missing designated root recipient' }
    if ((Get-FileHash -Algorithm SHA256 '/usr/local/sbin/rhel10-stig-aide-check').Hash -cne '6C561DA25F605118108D58D2BC4F7904F0A9A7C7D8DC48F10A3960BC7D682E83') { throw 'Unexpected content: /usr/local/sbin/rhel10-stig-aide-check' }
    if ((Run-Checked 'stat' @('-c', '%u:%g:%a', '/usr/local/sbin/rhel10-stig-aide-check')) -cne '0:0:700') { throw 'Unsafe ownership or mode: /usr/local/sbin/rhel10-stig-aide-check' }
    if ((Get-FileHash -Algorithm SHA256 '/etc/systemd/system/rhel10-stig-aide.service').Hash -cne 'B69BBE078D2720A6DDDAB62CCEF2CD3972E45978500F534D2B8268A238B6B5F4') { throw 'Unexpected content: /etc/systemd/system/rhel10-stig-aide.service' }
    if ((Run-Checked 'stat' @('-c', '%u:%g:%a', '/etc/systemd/system/rhel10-stig-aide.service')) -cne '0:0:644') { throw 'Unsafe ownership or mode: /etc/systemd/system/rhel10-stig-aide.service' }
    if ((Get-FileHash -Algorithm SHA256 '/etc/systemd/system/rhel10-stig-aide.timer').Hash -cne 'DBD84D1A8949E049FE60E9B4D94EAB3BEEAC15329D9BA54FAECAAD0678505322') { throw 'Unexpected content: /etc/systemd/system/rhel10-stig-aide.timer' }
    if ((Run-Checked 'stat' @('-c', '%u:%g:%a', '/etc/systemd/system/rhel10-stig-aide.timer')) -cne '0:0:644') { throw 'Unsafe ownership or mode: /etc/systemd/system/rhel10-stig-aide.timer' }
    return @{ Valid = $true; Results = "Daily persistent AIDE timer active; next scan: $next; exact managed scan/mail script and units verified; Postfix active, root alias: $recipient. Delivery and recipient ownership require site verification." }
} catch {
    return @{ Valid = $false; Results = "V-280980 validation failed: $($_.Exception.Message)" }
}

$ErrorActionPreference = 'Stop'
try {
    function Run-Checked([string]$Program, [string[]]$Arguments) {
        $output = @(& $Program @Arguments 2>&1)
        if ($LASTEXITCODE -ne 0) { throw "$Program failed: $output" }
        return ($output -join "`n").Trim()
    }
    if ((Run-Checked 'systemctl' @('is-enabled', 'rsyslog.service')) -cne 'enabled') { throw 'rsyslog is not enabled' }
    if ((Run-Checked 'systemctl' @('is-active', 'rsyslog.service')) -cne 'active') { throw 'rsyslog is not active' }
    Run-Checked 'rsyslogd' @('-N1') | Out-Null
    # Fresh unique probes verify every cron severity, including debug.
    # This functional check intentionally writes eight identifiable test log records.
    $token = 'STIG-TEST-CRON-LOGGING-' + [guid]::NewGuid().ToString('N')
    $levels = @('emerg', 'alert', 'crit', 'err', 'warning', 'notice', 'info', 'debug')
    foreach ($level in $levels) {
        Run-Checked 'logger' @('-p', "cron.$level", '-t', 'V-280991-validation', "$token-$level") | Out-Null
    }
    $missing = @($levels)
    for ($attempt = 0; $attempt -lt 20; $attempt++) {
        $log = (Get-Content -LiteralPath '/var/log/cron' -Tail 1000) -join "`n"
        $missing = @($levels | Where-Object { -not $log.Contains("$token-$_") })
        if ($missing.Count -eq 0) { break }
        Start-Sleep -Milliseconds 500
    }
    if ($missing.Count -gt 0) { throw "Cron messages missing from /var/log/cron: $($missing -join ', ')" }
    return @{ Valid = $true; Results = "rsyslog enabled/active and configuration valid. Fresh cron probes at all eight severities reached /var/log/cron; token: $token" }
} catch {
    return @{ Valid = $false; Results = "V-280991 validation failed: $($_.Exception.Message)" }
}

$ErrorActionPreference = 'Stop'
try {
    $source = (Get-Content -Raw -LiteralPath '/etc/grub.d/01_users').Replace("`r`n", "`n").Trim()
    $compiled = (Get-Content -Raw -LiteralPath '/etc/grub2.cfg').Replace("`r`n", "`n")
    $names = [regex]::Matches($compiled, '(?m)^\s*set superusers="([A-Za-z][A-Za-z0-9_-]*)"\s*$')
    if ($names.Count -ne 1) { throw 'Expected exactly one nonempty GRUB superuser assignment' }
    $account = $names[0].Groups[1].Value
    if ($account.ToLowerInvariant() -in @('root','admin','administrator','superuser','unlock')) { throw 'Common GRUB account name' }
    # Match the complete role-managed block, not isolated lines in inactive text.
    $expectedBlock = @'
if [ -f ${prefix}/user.cfg ]; then
  source ${prefix}/user.cfg
  if [ -n "${GRUB2_PASSWORD}" ]; then
    set superusers="__ACCOUNT__"
    export superusers
    password_pbkdf2 __ACCOUNT__ ${GRUB2_PASSWORD}
  fi
fi
'@
    $expectedBlock = $expectedBlock.Replace('__ACCOUNT__', $account).Trim()
    $blocks = [regex]::Matches($compiled, '(?s)### BEGIN /etc/grub.d/01_users ###\s*\n(.*?)\n### END /etc/grub.d/01_users ###')
    if ($blocks.Count -ne 1 -or $blocks[0].Groups[1].Value.Trim() -cne $expectedBlock) { throw 'Generated GRUB authentication block differs from expected configuration' }
    $expectedSource = @'
#!/usr/bin/sh -e
# Managed by Ansible - V-281167
cat << EOF
if [ -f \${prefix}/user.cfg ]; then
  source \${prefix}/user.cfg
  if [ -n "\${GRUB2_PASSWORD}" ]; then
    set superusers="__ACCOUNT__"
    export superusers
    password_pbkdf2 __ACCOUNT__ \${GRUB2_PASSWORD}
  fi
fi
EOF
'@
    if ($source -cne $expectedSource.Replace('__ACCOUNT__', $account).Trim()) { throw 'Persistent GRUB generator differs from expected configuration' }
    if ([regex]::Matches($compiled, '(?m)^\s*(?:set\s+)?superusers\s*=').Count -ne 1 -or
        [regex]::Matches($compiled, '(?m)^\s*password(?:_pbkdf2)?\s+').Count -ne 1) { throw 'Additional authentication directives require review' }
    $password = (Get-Content -Raw -LiteralPath '/boot/grub2/user.cfg').Trim()
    if ($password -cnotmatch '^GRUB2_PASSWORD=grub\.pbkdf2\.sha512\.[1-9][0-9]*\.[A-Fa-f0-9]+\.[A-Fa-f0-9]+$') { throw 'Missing or malformed GRUB PBKDF2 password' }
    $ownerMode = @(& stat -c '%u:%g:%a' /boot/grub2/user.cfg 2>&1)
    if ($LASTEXITCODE -ne 0 -or ($ownerMode -join '').Trim() -cne '0:0:600') { throw 'Unsafe GRUB password file ownership or mode' }
    & grub2-script-check /etc/grub2.cfg 2>&1 | Out-Null
    if ($LASTEXITCODE -ne 0) { throw 'Generated GRUB configuration failed syntax validation' }
    return @{ Valid = $true; Results = "GRUB account '$account' is nondefault and outside the DISA/evaluator common-name examples. Persistent generator and generated authentication block match; export and matching PBKDF2 binding verified; protected password file present. No password material disclosed. Boot-console interaction was not tested." }
} catch {
    return @{ Valid = $false; Results = "V-281167 validation failed: $($_.Exception.Message)" }
}

$ErrorActionPreference = 'Stop'
try {
    function Run-Checked([string]$Program, [string[]]$Arguments) {
        $value = @(& $Program @Arguments 2>&1)
        if ($LASTEXITCODE -ne 0) { throw "$Program failed" }
        return ($value -join "`n").Trim()
    }
    $approvalPath = '/etc/security/rhel10-stig-approved-local-accounts.json'
    if ((Run-Checked 'stat' @('-c', '%u:%g:%a', $approvalPath)) -cne '0:0:600') { throw 'Unsafe approval record ownership or mode' }
    $approved = @(ConvertFrom-Json -InputObject (Get-Content -Raw -LiteralPath $approvalPath))
    if ($approved.Count -eq 0 -or @($approved | Select-Object -Unique).Count -ne $approved.Count) { throw 'Empty or duplicate approval list' }
    foreach ($name in $approved) {
        if ($name -isnot [string] -or $name -cnotmatch '^[A-Za-z_][A-Za-z0-9_.-]*[$]?$') { throw 'Invalid approval record' }
    }
    $lines = @(Get-Content -LiteralPath '/etc/passwd')
    $interactive = @()
    $seen = @()
    foreach ($line in $lines) {
        $fields = $line.Split(':')
        if ($fields.Count -ne 7 -or $fields[2] -notmatch '^\d+$' -or $fields[3] -notmatch '^\d+$' -or $fields[0] -cin $seen) { throw 'Malformed or duplicate passwd entry' }
        $seen += $fields[0]
        # Include low-UID and empty/custom shells conservatively; do not hide locked accounts.
        if ($fields[6] -cmatch '/(?:nologin|false|sync|shutdown|halt)$') { continue }
        $name = $fields[0]
        if ($name -cnotin $approved) { throw "Unapproved interactive account: $name" }
        if ($fields[2] -eq '0') {
            if ($name -cne 'root') { throw 'Additional UID zero account requires review' }
        } else {
            $sudo = Run-Checked 'sudo' @('-n', '-l', '-U', $name)
            if ($sudo -notmatch '(?m)^\s*\(ALL(?:\s*:\s*ALL)?\)\s+(?:NOPASSWD:\s*)?ALL\s*$') { throw "Cannot confirm approved privileged access: $name" }
        }
        $interactive += $name
    }
    if ($interactive.Count -eq 0) { throw 'No account evidence read' }
    $status = Run-Checked 'auditctl' @('-s')
    if ($status -notmatch '(?m)^enabled\s+[12]$' -or $status -notmatch '(?m)^pid\s+[1-9][0-9]*$') { throw 'Auditing is not enabled with a running daemon' }
    $runtime = Run-Checked 'auditctl' @('-l')
    if ($runtime -match '(?m)^-a\s+(?:never,(?:task|exit)|(?:task|exit),never)(?:\s|$)') { throw 'Potentially suppressing audit rule requires review' }
    $persistent = (Get-Content -LiteralPath '/etc/audit/rules.d/30-rhel10-stig.rules') -join "`n"
    $compiled = (Get-Content -LiteralPath '/etc/audit/audit.rules') -join "`n"
    foreach ($arch in @('b32','b64')) {
        $pattern = '(?m)^-a always,exit -F arch=' + $arch + '(?: -S [a-z0-9_,]+)? -F path=/etc/passwd -F perm=wa (?:-F key=|-k )identity\s*$'
        foreach ($evidence in @($runtime, $persistent, $compiled)) {
            if ($evidence -cnotmatch $pattern) { throw "Missing unfiltered $arch passwd change audit rule" }
        }
    }
    return @{ Valid = $true; Results = "Local interactive accounts match the approved privileged list: $($interactive -join ', '). Privileged access confirmed; passwd changes monitored by enabled auditing with b32/b64 runtime, persistent and compiled rules. Approval remains an SA/ISSO policy record, not inferred from audit coverage." }
} catch {
    return @{ Valid = $false; Results = "V-281199 validation failed: $($_.Exception.Message)" }
}

$ErrorActionPreference = 'Stop'
try {
    $python = @'
import os, stat, subprocess, json, re
from pathlib import Path

def scan():
    homes = {Path('/root')}
    entries = Path('/etc/passwd').read_text().splitlines()
    if not entries:
        raise ValueError('Empty local account inventory')
    for line in entries:
        fields = line.split(':')
        if len(fields) != 7 or not fields[5].startswith('/'):
            raise ValueError('Malformed local account home record')
        homes.add(Path(fields[5]))
    if Path('/home').exists():
        homes.update(p for p in Path('/home').iterdir() if p.is_dir())
    directories = []
    protected = []
    files_checked = 0
    for directory in sorted({p / '.ssh' for p in homes}):
        try:
            info = directory.lstat()
        except FileNotFoundError:
            continue
        if stat.S_ISLNK(info.st_mode) or not stat.S_ISDIR(info.st_mode):
            raise ValueError(f'Review non-directory or linked SSH directory: {directory}')
        directories.append(str(directory))
        def walk_error(error):
            raise error
        for current, subdirs, files in os.walk(directory, onerror=walk_error):
            for name in subdirs:
                if (Path(current) / name).is_symlink():
                    raise ValueError(f'Review linked SSH subdirectory: {Path(current) / name}')
            for name in files:
                path = Path(current) / name
                info = path.stat()  # Follow file links; missing/unreadable targets fail closed.
                if not stat.S_ISREG(info.st_mode):
                    raise ValueError(f'Review nonregular SSH file: {path}')
                with path.open('rb') as stream:
                    header = stream.read(4096)
                files_checked += 1
                private = b'PRIVATE KEY' in header or header.startswith(b'PuTTY-User-Key-File-')
                standard_name = name.startswith('id_') and not name.endswith(('.pub', '-cert.pub'))
                if not private and not standard_name:
                    continue
                if not re.search(br'-----BEGIN (?:OPENSSH |RSA |DSA |EC |ENCRYPTED )?PRIVATE KEY-----', header):
                    raise ValueError(f'Unsupported or malformed private-key candidate: {path}')
                result = subprocess.run(
                    ['ssh-keygen', '-y', '-P', '', '-f', str(path)],
                    stdout=subprocess.DEVNULL, stderr=subprocess.PIPE,
                    timeout=10, env={**os.environ, 'LC_ALL': 'C'}, check=False)
                if result.returncode == 0:
                    raise ValueError(f'Private key opens without a passphrase: {path}')
                # A nonzero exit alone is not evidence of encryption.
                if b'incorrect passphrase supplied to decrypt private key' not in result.stderr.lower():
                    raise ValueError(f'Cannot confirm passphrase protection for key: {path}')
                protected.append(str(path))
    return {'valid': True, 'results': 'Scanned local passwd home .ssh directories plus /home/*/.ssh and /root/.ssh; '
            + f'{len(directories)} directories, {files_checked} files, {len(protected)} protected private keys. '
            + ('No private-key candidates found.' if not protected else 'Protected key paths: ' + ', '.join(protected))
            + ' Scope excludes private keys stored outside these directories; site procedure prohibits such unregistered storage.'}

try:
    print(json.dumps(scan()))
except Exception as error:
    # Only paths/reasons; never expose key material or ssh-keygen output.
    print(json.dumps({'valid': False, 'results': str(error)}))
'@
    $output = @(& python3 -c $python 2>&1)
    if ($LASTEXITCODE -ne 0) { throw 'Private-key inventory helper failed' }
    $check = ConvertFrom-Json -InputObject ($output -join "`n")
    if ($check.valid -isnot [bool]) { throw 'Invalid validation result' }
    return @{ Valid = $check.valid; Results = "V-281326: $($check.results)" }
} catch {
    return @{ Valid = $false; Results = 'V-281326 could not complete the private-key inventory/check; manual review required.' }
}

$ErrorActionPreference = 'Stop'
try {
    $helper = '/usr/local/sbin/rhel10-stig-firewall-validate'
    if ((Get-FileHash -Algorithm SHA256 -LiteralPath $helper).Hash -cne 'F7A46B35CA2F0B499F8F5F92150842CFF273AE6236529C5D0112CE1BC0BFF15C') { throw 'Firewall validator changed; review required' }
    $mode = @(& stat -c '%u:%g:%a' $helper 2>&1)
    if ($LASTEXITCODE -ne 0 -or ($mode -join '').Trim() -cne '0:0:700') { throw 'Unsafe firewall validator ownership or mode' }
    $output = @(& python3 $helper 2>&1)
    if ($LASTEXITCODE -ne 0) { throw 'Firewall validator failed' }
    $check = ($output -join "`n") | ConvertFrom-Json
    if ($check.valid -isnot [bool]) { throw 'Invalid firewall validation result' }
    return @{ Valid = $check.valid; Results = [string]$check.results }
} catch {
    return @{ Valid = $false; Results = "Firewall validation could not complete: $($_.Exception.Message)" }
}

