$ErrorActionPreference = 'Stop'
try {
    # Existence-only production decision, explicitly requested by the owner.
    $candidates = @('/opt/splunkforwarder/bin/splunk')
    $rpm = @(& rpm -ql splunkforwarder 2>$null)
    if ($LASTEXITCODE -eq 0) {
        $candidates += @($rpm | Where-Object { $_ -cmatch '^/.+/bin/splunk$' })
    }
    foreach ($cli in @($candidates | Select-Object -Unique)) {
        $daemon = Join-Path (Split-Path -Parent $cli) 'splunkd'
        if ([System.IO.File]::Exists($cli) -and [System.IO.File]::Exists($daemon)) {
            $cliInfo = Get-Item -LiteralPath $cli
            $daemonInfo = Get-Item -LiteralPath $daemon
            if ($cliInfo.Length -gt 0 -and $daemonInfo.Length -gt 0) {
                return @{ Valid = $true; Results = "Splunk Universal Forwarder installation detected: $cli and $daemon. Production owner assumption applied; configuration, receiver authentication, TLS, service state and ingestion were not checked." }
            }
        }
    }
    return @{ Valid = $false; Results = 'No recognized Splunk Universal Forwarder installation detected; status remains/reverts to Not Reviewed. Standard /opt/splunkforwarder or paths registered by the splunkforwarder RPM are checked. Review custom installations manually.' }
} catch {
    return @{ Valid = $false; Results = 'Splunk Universal Forwarder presence could not be established; Not Reviewed. No configuration correctness is asserted.' }
}

